@* Vertical sidebar navigation for settings sections *@

<nav class="settings-sidebar">
    <h5 class="settings-sidebar-title">Settings</h5>
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="settings-nav-icon">@GetIcon(section)</span>
                <span>@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_4a5dec01fbf94e26831e990c062cd236.Models

<div class="settings-section">
    <h3>Profile</h3>
    <p class="text-muted">Manage your personal information</p>
    <hr />

    <div class="profile-avatar-area mb-4">
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(AvatarUrl))
            {
                <img src="@AvatarUrl" alt="Avatar" class="avatar-img" />
            }
            else
            {
                <div class="avatar-placeholder">No Avatar</div>
            }
        </div>
        <div class="avatar-url-display">
            <small class="text-muted">Avatar URL:</small>
            <code>@(string.IsNullOrWhiteSpace(AvatarUrl) ? "(none)" : AvatarUrl)</code>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label" for="displayName">Display Name</label>
        <input id="displayName" type="text" class="form-control" @bind="DisplayName" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="email">Email</label>
        <input id="email" type="email" class="form-control" @bind="Email" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="bio">Bio</label>
        <textarea id="bio" class="form-control" rows="4" @bind="Bio"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(Message))
    {
        <div class="alert @(IsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @Message
            <button type="button" class="btn-close" @onclick="() => Message = null"></button>
        </div>
    }

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private string? Message;
    private bool IsError;
    private bool IsSaving;

    // Snapshot for discard
    private UserProfile? _lastSaved;

    protected override void OnParametersSet()
    {
        if (Profile is not null && _lastSaved is null)
        {
            LoadFrom(Profile);
            _lastSaved = Profile;
        }
    }

    private void LoadFrom(UserProfile p)
    {
        DisplayName = p.DisplayName;
        Email = p.Email;
        AvatarUrl = p.AvatarUrl;
        Bio = p.Bio;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        Message = null;
        try
        {
            var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
            await OnSave.InvokeAsync(updated);
            _lastSaved = updated;
            Message = "Profile saved successfully!";
            IsError = false;
        }
        catch
        {
            Message = "Failed to save profile.";
            IsError = true;
        }
        finally
        {
            IsSaving = false;
        }
    }

    private void Discard()
    {
        if (_lastSaved is not null)
        {
            LoadFrom(_lastSaved);
            Message = null;
        }
    }
}

@using sv_4a5dec01fbf94e26831e990c062cd236.Models

<div class="settings-section">
    <h3>Notifications</h3>
    <p class="text-muted">Control how you receive notifications</p>
    <hr />

    <div class="mb-4">
        <h5>Notification Channels</h5>

        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>

        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>

        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-4">
        <h5>Muted Channels</h5>
        <p class="text-muted small">Check channels you want to mute</p>
        @foreach (var channel in AllChannels)
        {
            <div class="form-check mb-1">
                <input class="form-check-input" type="checkbox" id="ch-@channel"
                       checked="@MutedSet.Contains(channel)"
                       @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                <label class="form-check-label" for="ch-@channel">#@channel</label>
            </div>
        }
    </div>

    @if (!string.IsNullOrEmpty(Message))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @Message
            <button type="button" class="btn-close" @onclick="() => Message = null"></button>
        </div>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
        @if (IsSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private HashSet<string> MutedSet = new();
    private string? Message;
    private bool IsSaving;
    private bool _initialized;

    private static readonly List<string> AllChannels =
        ["general", "announcements", "random", "dev-talk", "design", "support"];

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedSet = new HashSet<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted) MutedSet.Add(channel);
        else MutedSet.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        Message = null;
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, MutedSet.ToList());
        await OnSave.InvokeAsync(updated);
        Message = "Notification preferences saved!";
        IsSaving = false;
    }
}

@* Confirmation dialog before revoking a session *@

@if (IsVisible)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal d-block fade show" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session?</p>
                    @if (Session is not null)
                    {
                        <dl class="row mb-0">
                            <dt class="col-4">Device</dt>
                            <dd class="col-8">@Session.Device</dd>
                            <dt class="col-4">Location</dt>
                            <dd class="col-8">@Session.Location</dd>
                        </dl>
                    }
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    using sv_4a5dec01fbf94e26831e990c062cd236.Models;

    [Parameter] public bool IsVisible { get; set; }
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@using sv_4a5dec01fbf94e26831e990c062cd236.Models

<div class="settings-section">
    <h3>Security</h3>
    <p class="text-muted">Manage your account security</p>
    <hr />

    <div class="mb-4">
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />
    </div>

    <div class="mb-4">
        <h5>Two-Factor Authentication</h5>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@TwoFactorEnabled"
                       @onchange="e => TwoFactorEnabled = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="twoFactor">Enable 2FA</label>
            </div>
            <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <small class="text-muted d-block mt-2">
                Last password change: @Settings.LastPasswordChange.Value.ToString("MMM dd, yyyy 'at' HH:mm UTC")
            </small>
        }
    </div>

    <div class="mb-4">
        <h5>Active Sessions</h5>
        @if (Sessions.Count == 0)
        {
            <p class="text-muted">No active sessions.</p>
        }
        else
        {
            <div class="table-responsive">
                <table class="table table-hover">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Sessions)
                        {
                            var isCurrent = session == Sessions.FirstOrDefault();
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrent)
                                    {
                                        <span class="badge bg-info ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrent)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
    </div>

    <RevokeSessionDialog IsVisible="_showRevokeDialog"
                         Session="_sessionToRevoke"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled;
    private List<ActiveSession> Sessions = new();
    private bool _initialized;

    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            if (!_initialized)
            {
                TwoFactorEnabled = Settings.TwoFactorEnabled;
                _initialized = true;
            }
            Sessions = Settings.Sessions;
        }
    }

    private async Task HandleChangePassword((string Current, string New) args) =>
        await OnChangePassword.InvokeAsync(args);

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
        }
        _showRevokeDialog = false;
        _sessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        _showRevokeDialog = false;
        _sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
