            </div>
            <div class="mb-3">
                <label class="form-label" for="confirmPw">Confirm Password</label>
                <input id="confirmPw" type="password" class="form-control" @bind="ConfirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(Message))
            {
                <div class="alert @(IsError ? "alert-danger" : "alert-success") small py-2">@Message</div>
            }

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@IsUpdating">
                @if (IsUpdating)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? Message;
    private bool IsError;
    private bool IsUpdating;

    private async Task UpdatePasswordAsync()
    {
        Message = null;

        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            Message = "Current password is required.";
            IsError = true;
            return;
        }
        if (NewPassword.Length < 6)
        {
            Message = "New password must be at least 6 characters.";
            IsError = true;
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            Message = "Passwords do not match.";
            IsError = true;
            return;
        }

        IsUpdating = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            Message = "Password updated successfully!";
            IsError = false;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch
        {
            Message = "Failed to update password.";
            IsError = true;
        }
        finally
        {
            IsUpdating = false;
        }
    }
}
