toolArgs.file_text:
@* Live preview of appearance settings *@

<div class="appearance-preview-container p-3 border rounded @ThemeClass @FontClass"
     style="@(CompactMode ? "line-height:1.2;" : "")">
    <div class="preview-header mb-2">
        <strong>Preview</strong>
    </div>
    <div class="preview-nav mb-2 d-flex gap-2">
        <span class="preview-nav-item active">Dashboard</span>
        <span class="preview-nav-item">Settings</span>
        <span class="preview-nav-item">Profile</span>
    </div>
    <div class="preview-card p-2 mb-2 rounded">
        <div class="preview-card-title fw-bold">Sample Card</div>
        <p class="mb-1">This is how your content will look with the selected appearance settings.</p>
        <button class="btn btn-sm btn-primary">Action</button>
    </div>
    <div class="preview-meta">
        <small>Theme: @Theme &middot; Font: @FontSize &middot; Language: @Language &middot; Compact: @(CompactMode ? "On" : "Off")</small>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public string Language { get; set; } = "English";
    [Parameter] public bool CompactMode { get; set; }

    private string ThemeClass => Theme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string FontClass => FontSize switch
    {
        "Small" => "preview-font-sm",
        "Large" => "preview-font-lg",
        _ => "preview-font-md"
    };
}

@using sv_4a5dec01fbf94e26831e990c062cd236.Models

<div class="settings-section">
    <h3>Appearance</h3>
    <p class="text-muted">Customize the look and feel</p>
    <hr />

    <div class="row">
        <div class="col-md-6">
            <div class="mb-4">
                <h5>Theme</h5>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                               value="@theme" checked="@(Theme == theme)"
                               @onchange="() => Theme = theme" />
                        <label class="form-check-label" for="theme-@theme">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h5>Font Size</h5>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                               value="@size" checked="@(FontSize == size)"
                               @onchange="() => FontSize = size" />
                        <label class="form-check-label" for="fs-@size">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h5>Language</h5>
                <select class="form-select" @bind="Language">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <h5>Compact Mode</h5>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                    <label class="form-check-label" for="compactMode">Enable compact mode</label>
