@page "/settings"
@using sv_4a5dec01fbf94e26831e990c062cd236.Models
@using sv_4a5dec01fbf94e26831e990c062cd236.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="s => _activeSection = s" />

    <div class="settings-content">
        @if (_isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationPrefsAsync" />
                    break;
                case "Security":
                    <SecuritySection Settings="@_security"
                                     OnChangePassword="HandleChangePasswordAsync"
                                     OnRevokeSession="HandleRevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@_appearance" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _isLoading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllAsync();
        _isLoading = false;
    }

    private async Task LoadAllAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _notificationPrefs = notifsTask.Result;
        _security = securityTask.Result;
        _appearance = appearanceTask.Result;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

/* ── Settings Dashboard Layout ── */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
}

/* ── Sidebar ── */
.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.settings-sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.65rem 1.25rem;
    cursor: pointer;
    color: #495057;
    font-size: 0.95rem;
    transition: background 0.15s, color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.settings-nav-icon {
    font-size: 1.1rem;
}

/* ── Content Area ── */
.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h3 {
    margin-bottom: 0.25rem;
}

/* ── Profile Avatar ── */
.profile-avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    flex-shrink: 0;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
    font-size: 0.75rem;
}

.avatar-url-display code {
    word-break: break-all;
    font-size: 0.8rem;
}

/* ── Appearance Preview ── */
.appearance-preview-container {
    transition: all 0.2s;
}

.preview-light {
    background: #ffffff;
    color: #212529;
    border-color: #dee2e6 !important;
}

.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a !important;
}

.preview-dark .preview-card {
    background: #313244;
}

.preview-dark .preview-nav-item {
    color: #a6adc8;
}

.preview-dark .preview-nav-item.active {
    color: #89b4fa;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #495057;
    border-color: #8888aa !important;
}

.preview-font-sm {
    font-size: 0.8rem;
}

.preview-font-md {
    font-size: 0.95rem;
}

.preview-font-lg {
    font-size: 1.15rem;
}

.preview-nav-item {
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    cursor: default;
    color: #6c757d;
    font-size: 0.85em;
}

.preview-nav-item.active {
    background: #0d6efd;
    color: #fff;
}

.preview-card {
    background: #f8f9fa;
    border: 1px solid #e9ecef;
}

.preview-card-title {
    font-size: 1em;
}

.preview-meta {
    color: #6c757d;
}

/* ── Change Password Panel ── */
.change-password-panel .password-form {
    background: #fafafa;
}

